widget.client_script:
function ($scope, $location, $rootScope, spUtil, $interpolate, spAriaFocusManager, $timeout, $http, $window) {
	var c = this;

	var BYTES_100MB = 100 * 1024 * 1024;

	$scope.exceedsMax = false;
	$scope.maxCount = 0;

	$scope.allCheckboxesDisabled = false;
	function recordBytes(rec) {
		try { return parseInt(rec.secondary_fields[1].display_value, 10) || 0; }
		catch (e) { return 0; }
	}
	function isBig(rec) { return recordBytes(rec) >= BYTES_100MB; }
	function forEachRecord(fn) {
		if ($scope.c.data.obj && Array.isArray($scope.c.data.obj.records)) {
			$scope.c.data.obj.records.forEach(function(file) {
				if (file && file.record) fn(file.record, file);
			});
		}
		if (Array.isArray($scope.c.data.allTags)) {
			for (var level = 0; level < $scope.c.data.allTags.length; level++) {
				var tagGroup = $scope.c.data.allTags[level] || [];
				tagGroup.forEach(function(tagObj) {
					var files = $scope.getFiles(tagObj, level) || [];
					files.forEach(function(file) {
						(file.records || []).forEach(function(rec) { fn(rec, file, tagObj, level); });
					});
				});
			}
		}
	}
	$scope.anySmallSelected = false;
	$scope.anyBigSelected   = false;
	$scope.updateSelectionLocks = function () {
		var big = false, small = false;
		forEachRecord(function(rec) {
			if (rec.checked) {
				if (isBig(rec)) big = true; else small = true;
			}
		});
		$scope.anyBigSelected = big;
		$scope.anySmallSelected = small;
	};
	$scope.isCheckboxDisabled = function (rec) {
		if (!rec) return false;
		if (rec.checked) return false;
		if ($scope.anyBigSelected) return true;
		if ($scope.anySmallSelected && isBig(rec)) return true;
		return false;
	};
$scope.debug = false;

	this.data.filterText = "";
	this.showFilter = false;
	this.onClick = function($event, item, url, action) {
		$event.stopPropagation();
		$event.preventDefault();
		if (typeof url == "string") {
			var urlExp = $interpolate(url);
			url = urlExp(item);
			$location.url(url);
		} else if (url && typeof url == "object")
			$location.search(url);
		else {
			var evt = {};
			evt.url = url;
			evt.table = item.className;
			evt.sys_id = item.sys_id;
			evt.record = item;
			evt.rectangle_id = c.options.sys_id;
			evt.action = action;
			$location.search('sl_sys_id', evt.sys_id);
			$location.search('sl_table', evt.table);
$location.search('spa', 1);
			$rootScope.$broadcast('$sp.list.click', evt);
		}
		$rootScope.$on('sp.page.loaded', function() {
			$timeout(function(){
				spAriaFocusManager.focusOnPageTitle();
			})
		})
	};

	$scope.checkForPostBid = function(topTag){
		if(topTag == 'plans' || topTag == 'specs' || topTag == 'supplemental_info' || topTag == 'notice'){
			return false;
		}

		return true;
	};

	$scope.formatTag = function(tag) {
		switch(tag){
			case 'plans':
				return 'Project Plans';
			case 'specs':
				return 'Notice to Bidders & Special Provisions';
		}

		if (!tag) return "";
return tag.replace(/_/g, ' ').replace(/\b\w/g, function(match) {
			return match.toUpperCase();
		});
  };

	$scope.formatSize = function(bytes) {
		if (bytes >= 1024 * 1024) {
return (bytes / (1024 * 1024)).toFixed(2) + " Mb";
    } else {
return (bytes / 1024).toFixed(2) + " Kb";
    }
	};

	$scope.getIcon = function(filename){
		var ext = filename.slice(-3).toLowerCase();
		switch(ext){
			case 'pdf':
				return 'doc-pdf-icon.png';
			case 'ppf':
				return 'doc-ppf-icon.png';
			case 'dgn':
				return 'dgn.png';
			case 'xml':
				return 'xml.png';
			case 'dwg':
				return 'dwg.png';
			case 'lnk':
				return 'lnk.png';
			default:
				return '';
		}
	};

	$scope.getTotalBytes = function() {
			var totalBytes = 0;
			var totalFiles = 0;

			if($scope.c.data.allTags) {
				for (var level = 0; level < $scope.c.data.allTags.length; level++) {
					var tagGroup = $scope.c.data.allTags[level];
					for (var i = 0; i < tagGroup.length; i++) {
						var tagObj = tagGroup[i];
						var files = $scope.getFiles(tagObj, level);
						for (var j = 0; j < files.length; j++) {
							var file = files[j];
							for (var k = 0; k < file.records.length; k++) {
								var record = file.records[k];
								if(record.checked){
									totalBytes += parseInt(record.secondary_fields[1].display_value);
									totalFiles++;
								}
							}
						}
					}
				}
			}

			if($scope.c.data.obj.records) {
				for(var u = 0; u < $scope.c.data.obj.records.length; u++){
					if($scope.c.data.obj.records[u].record.checked){
						totalBytes += parseInt($scope.c.data.obj.records[u].record.secondary_fields[1].display_value);
						totalFiles++;
					}
				}
			}

			if(totalFiles > 1){
				if(totalBytes > BYTES_100MB){
					$scope.downloadButtonDisabled = true;
					$scope.exceedsMax = true;
					$scope.maxCount++;
				}
				else{
					$scope.downloadButtonDisabled = false;
					$scope.exceedsMax = false;
					$scope.maxCount = 0;
				}
				if($scope.exceedsMax && $scope.maxCount < 2){
					$timeout(function () {
						alert('The selected files are over the 100MB limit, please select a smaller set of files for download.');
					}, 100);
				}
			}

			if(totalBytes < BYTES_100MB){
				$scope.downloadButtonDisabled = false;
				$scope.exceedsMax = false;
				$scope.maxCount = 0;
			}

			return $scope.formatSize(totalBytes);
	};

	$scope.getFiles = function(obj, index){	
		return $scope.c.data.allTags[index].filter(function(existingObj) {
			return existingObj.filePath === obj.filePath && obj.records.length > 0;
		}) || [];
	};

	$scope.checkFilePath = function(obj, subObj){
		var slicedSubPath = subObj.filePath.slice(0, -(subObj.tag.length + 1));
		return obj.filePath === slicedSubPath;
	};

	$scope.isAddenda = function(tag){
		if (tag.startsWith('ad') && tag.length < 5) {
			var num = tag.substring(2);
			if (!isNaN(num) && num.trim() != '') {
				return $scope.c.data.addendaPurposes[num-1];
			}
		}
		return null;
	};
	function toggleSubtree(obj, isChecked) {
		obj.checked = isChecked;
		if (obj.records && obj.records.length) {
			obj.records.forEach(function(rec) {
				if(!isBig(rec)){
					rec.checked = isChecked;
				}
			});
		}
		var childLevel = obj.level + 1;
		if ($scope.data.allTags[childLevel] && $scope.data.allTags[childLevel].length) {
			$scope.data.allTags[childLevel].forEach(function(child) {
				if (child.parentTag === obj.tag && $scope.checkFilePath(obj, child)) {
					toggleSubtree(child, isChecked);
				}
			});
		}
	}

	function bubbleUp(childObj) {
		var parentObj;
		if (childObj.level === 0) {
			parentObj = $scope.data.obj;
		} else {
			var parentLevel = childObj.level - 1;
			parentObj = $scope.data.allTags[parentLevel].find(function(o) {
				return o.tag === childObj.parentTag && $scope.checkFilePath(o, childObj);
			});
		}
		if (!parentObj) return;
		var recordsChecked = true;
		if (parentObj.records && parentObj.records.length) {
			recordsChecked = parentObj.records.every(function(rec) {
				return rec.checked;
			});
		}
		var siblingsAllChecked = true;
		if (childObj.level >= 0 && $scope.data.allTags[childObj.level]) {
			var siblings = $scope.data.allTags[childObj.level].filter(function(sib) {
				return sib.parentTag === parentObj.tag && $scope.checkFilePath(parentObj, sib);
			});
			siblingsAllChecked = siblings.every(function(s) { return s.checked; });
		}
		parentObj.checked = recordsChecked && siblingsAllChecked;
		if (parentObj !== $scope.data.obj) {
			bubbleUp(parentObj);
		}
	}
	$scope.toggleChildren = function(obj, level) {
		var isChecked = obj.checked;
		if (level === 0 && obj.tag === $scope.data.obj.tag) {
			toggleSubtree(obj, isChecked);
			if ($scope.data.obj.records && $scope.data.obj.records.length) {
				$scope.data.obj.records.forEach(function(file) {
					if (file.record && !isBig(file.record)) {
						file.record.checked = isChecked;
					}
				});
			}
			$scope.data.obj.checked = isChecked;
		} else {
			toggleSubtree(obj, isChecked);
			bubbleUp(obj);
		}

		$scope.updateSelectionLocks();
	};
	$scope.checkParent = function(file, record, level) {
		var isChecked = record.checked;
		if (level === -1) {
			if (!isChecked) {
				$scope.data.obj.checked = false;
				return;
			}
			var allNoTagChecked = $scope.data.obj.records.every(function(f) {
				return f.record && f.record.checked;
			});
			$scope.data.obj.checked = allNoTagChecked;
			return;
		}
		var allRecordsChecked = file.records.every(function(rec) {
			return rec.checked;
		});
		file.checked = allRecordsChecked;
		bubbleUp(file);

		$scope.updateSelectionLocks();
	};

	$scope.isGroupDisabled = function () {
		return $scope.anyBigSelected === true;
	};

	$scope.downloadViaFetch = function(url, suggestedName) {
		return fetch(url, { credentials: 'include' }).then(function(res) {
			if (!res.ok) throw new Error('HTTP ' + res.status);
			var cd = res.headers.get('Content-Disposition');
			var nameFromHeader = null;
			if (cd) {
var m1 = /filename\*=(?:UTF-8'')?([^;]+)/i.exec(cd);
var m2 = /filename="([^"]+)"/i.exec(cd);
				if (m1 && m1[1]) nameFromHeader = decodeURIComponent(m1[1]);
				else if (m2 && m2[1]) nameFromHeader = m2[1];
			}
			return res.blob().then(function(blob) {
				$scope.triggerBlobSave(blob, nameFromHeader || suggestedName);
			});
		});
	};
	$scope.triggerBlobSave = function(blob, suggestedName) {
		var url = URL.createObjectURL(blob);
		var a = document.createElement('a');
		a.href = url;
		if (suggestedName) a.download = suggestedName;
		document.body.appendChild(a);
		a.click();
		document.body.removeChild(a);
		setTimeout(function(){ URL.revokeObjectURL(url); }, 0);
	};

	$scope.downloadZip = function ($event) {
		function setDisabled(state) {
			$scope.downloadButtonDisabled = state;
			$scope.allCheckboxesDisabled = state;
			if ($event && $event.currentTarget) $event.currentTarget.disabled = state;
		}
		setDisabled(true);
spUtil.addInfoMessage('Preparing your download... Please wait, this may take a few minutes.');
		try { $scope.server.update({ action: 'enqueue_info', message: 'Preparing your download... Please wait, this may take a few minutes.' }); } catch (e) {}
		$scope.$$postDigest(function () {
			requestAnimationFrame(function () {
				var selectedFiles = [];
				var ndaNeeded = false;
				if ($scope.c.data.allTags) {
					for (var level = 0; level < $scope.c.data.allTags.length; level++) {
						var tagGroup = $scope.c.data.allTags[level];
						for (var i = 0; i < tagGroup.length; i++) {
							var tagObj = tagGroup[i];
							var files = $scope.getFiles(tagObj, level);
							var tagForCheck = tagObj.tag ? tagObj.tag.toLowerCase() : "";
							for (var j = 0; j < files.length; j++) {
								var file = files[j];
								for (var k = 0; k < file.records.length; k++) {
									var record = file.records[k];
									if (record.checked) {
										selectedFiles.push({ sys_id: record.sys_id, filePath: file.filePath });
										if (tagForCheck === "plans") ndaNeeded = true;
									}
								}
							}
						}
					}
				}
				if ($scope.c.data.obj && $scope.c.data.obj.records) {
					for (var u = 0; u < $scope.c.data.obj.records.length; u++) {
						var noTagObj = $scope.c.data.obj.records[u];
						if (noTagObj.record.checked) {
							selectedFiles.push({ sys_id: noTagObj.record.sys_id, filePath: noTagObj.filePath });
						}
					}
				}
				if (selectedFiles.length === 0) {
					alert("No files selected.");
					setDisabled(false);
					$scope.isLoading = false;
					$scope.$applyAsync();
					return;
				}
				if (ndaNeeded) {
					if ($scope.c.data.isLoggedIn) {
						if ($scope.c.data.sendUserToNDA) {
							alert('NDA needed to download a selected file.');
							setDisabled(false);
$window.location.href = '/cc?id=cc_nda';
							return;
						}
					} else {
						alert('Need to be signed in to download a selected file.');
						setDisabled(false);
						$scope.isLoading = false;
						$scope.$applyAsync();
						return;
					}
				}
				$scope.isLoading = true;
				$scope.loadingMessage = "Creating ZIP file, please wait...";
